def nextLargerNodes(values: list[int]) -> list[int]:
    res = [0] * len(values)
    stack = []
    for i, v in enumerate(values):
        while stack and values[stack[-1]] < v:
            idx = stack.pop()
            res[idx] = v
        stack.append(i)
    return res

